{
  "verses": [
    {
      "chapter": 11,
      "text_ar": "فالان يا اولادي في حفظكم لهذه، لن يكون العدو متربصا بكم ولا نيايا شريرة في اذهانكم لان هذه هي تعويذة من الرب.",
      "verse": 21
    },
    {
      "chapter": 11,
      "text_ar": "فقوموا الان وشدوا هذه حولكم قبل ان اموت لكي تروا الملائكة ياتون عند فراقي ولكي تبصروا بعجب قوات الله.",
      "verse": 22
    },
    {
      "chapter": 11,
      "text_ar": "ثم قامت تلك التي اسمها النهار وشدت نفسها، وفي الحال فارقت جسدها كما قال ابوها، ولبست قلبا اخر كانها لم تهتم ابدا بالامور الارضية.",
      "verse": 23
    },
    {
      "chapter": 11,
      "text_ar": "وانشدت ترانيم ملائكية بصوت الملائكة، وهتفت بتسبيح الله الملائكي وهي ترقص.",
      "verse": 24
    },
    {
      "chapter": 11,
      "text_ar": "ثم ان الابنة الاخرى، المدعوة قاسيّة، لبست النطاق، فتحول قلبها حتى انها لم تعد ترغب في الامور العالمية.",
      "verse": 25
    }
  ],
  "book_code": "TJOB"
}
